const responses = $input.all().map((item) => item.json);
if (responses.length !== 1) {
  throw new Error(`Expected one HTTP response, received ${responses.length}`);
}

const response = responses[0];
if (response.statusCode !== 200) {
  throw new Error(`Unexpected HTTP status: ${response.statusCode}`);
}

const contentType = String(response.headers?.['content-type'] ?? response.headers?.['Content-Type'] ?? '');
if (!contentType.toLowerCase().includes('application/json')) {
  throw new Error('Unexpected response content type');
}

const records = response.body;
if (!Array.isArray(records) || records.length < 1 || records.length > 500) {
  throw new Error('Response must contain between 1 and 500 records');
}

const requiredStringFields = ['victim', 'group', 'discovered'];
const allowedFields = ['activity', 'attackdate', 'claim_url', 'country', 'description', 'discovered', 'domain', 'group', 'url', 'victim'];
const normalized = records.map((record, index) => {
  if (!record || typeof record !== 'object' || Array.isArray(record)) {
    throw new Error(`Record ${index + 1} must be an object`);
  }
  for (const field of requiredStringFields) {
    if (typeof record[field] !== 'string' || !record[field].trim()) {
      throw new Error(`Record ${index + 1} has invalid ${field}`);
    }
  }
  const safe = {};
  for (const field of allowedFields) {
    const value = record[field];
    if (value === undefined || value === null) {
      safe[field] = '';
    } else if (typeof value === 'string') {
      safe[field] = value.trim();
    } else {
      throw new Error(`Record ${index + 1} has invalid ${field}`);
    }
  }
  return safe;
});

return [{ json: { records: normalized } }];
